import{_ as i,C as r,o as s,c as o,j as e,a as h,E as l,a3 as n}from"./chunks/framework.Ba39LDvt.js";const E=JSON.parse('{"title":"EE219 智能计算系统","description":"从神经网络算子、量化和脉动阵列，到存储、编译与 Gemmini 集成的软硬件课程指南。","frontmatter":{"title":"EE219 智能计算系统","description":"从神经网络算子、量化和脉动阵列，到存储、编译与 Gemmini 集成的软硬件课程指南。"},"headers":[],"relativePath":"courses/ee219.md","filePath":"courses/ee219.md","lastUpdated":1795525517000}'),d={name:"courses/ee219.md"};function c(u,t,g,p,b,m){const a=r("CourseTable");return s(),o("div",null,[t[0]||(t[0]=e("h1",{id:"ee219-智能计算系统",tabindex:"-1"},[h("EE219 智能计算系统 "),e("a",{class:"header-anchor",href:"#ee219-智能计算系统","aria-label":'Permalink to "EE219 智能计算系统"'},"​")],-1)),l(a,{codes:"EE219"}),t[1]||(t[1]=n('<p>课程表采用 <strong>2026–2027 学年</strong>信息；内容与评分主要依据 <strong>2026 秋版本</strong>公开主页及课程笔记。往届版本教师可能不同，SIST 与其他教学班的实验安排也需分别核对。</p><h2 id="课程定位" tabindex="-1">课程定位 <a class="header-anchor" href="#课程定位" aria-label="Permalink to &quot;课程定位&quot;">​</a></h2><p>这门课关注“神经网络由什么硬件、按什么数据流计算出来”。它将算法、数字电路、体系结构、编译器与性能分析放在一条链上，适合希望从模型使用走向加速器设计的同学。</p><p>官方开课表列出线性代数、概率统计与 EE113，并推荐 CS100 / CS110、Verilog 或 VHDL、Python 基础。部分往届笔记写“先修无”，本页不据此覆盖正式开课表；选课资格以教务系统为准。建议先掌握<a href="/shanghaitech-ic-wiki-dev.github.io/courses/cs110">CS110</a>的存储层次与并行概念、<a href="/shanghaitech-ic-wiki-dev.github.io/courses/ee113">EE113</a>的电路与时序基础。与<a href="/shanghaitech-ic-wiki-dev.github.io/courses/cs290u">CS290U</a>的区别是：后者侧重模型工程，本课进一步解释算法与硬件的映射。</p><h2 id="内容主线" tabindex="-1">内容主线 <a class="header-anchor" href="#内容主线" aria-label="Permalink to &quot;内容主线&quot;">​</a></h2><p>按 2026 秋公开周历归并如下；后续更新以课程主页为准。</p><table tabindex="0"><thead><tr><th>周次</th><th>主线</th><th>关键问题</th></tr></thead><tbody><tr><td>1–3</td><td>神经网络、基本算子与训练背景</td><td>网络如何化为矩阵、卷积和向量计算？</td></tr><tr><td>4–5</td><td>量化与模型压缩</td><td>数值表示与稀疏性如何改变计算和存储代价？</td></tr><tr><td>5–7</td><td>核心电路、数据通路、脉动阵列与 Verilog</td><td>数据何时进入处理单元，部分和在哪里累积？</td></tr><tr><td>7–9</td><td>体系结构、SIMD、屋顶线（Roofline）模型、ISA 与存储</td><td>瓶颈来自算力、带宽还是利用率？</td></tr><tr><td>9–10</td><td>系统设计、软件栈与机器学习编译器</td><td>调度、映射与内存管理怎样共同影响性能？</td></tr><tr><td>10–11</td><td>稀疏计算与存内计算</td><td>非规则计算和新型存储如何改变系统设计？</td></tr></tbody></table><p>课程初始笔记还列有新兴计算、类脑计算等主题，但不将计划内容表述为已经完成的课堂进度。</p><h2 id="实验-项目" tabindex="-1">实验 / 项目 <a class="header-anchor" href="#实验-项目" aria-label="Permalink to &quot;实验 / 项目&quot;">​</a></h2><p>2026 秋笔记记录了 PyTorch 环境、NumPy CNN 推理与反向传播、模型压缩、查找表与脉动矩阵乘法等实验，并进一步进入 <strong>Gemmini 输出驻留（Output-Stationary，OS）分块调度与 Mesh 集成</strong>。</p><p>Lab4 将调度器、阵列实现和 Chipyard 性能测试连接起来。学习重点包括分块的遍历顺序、累加状态、尾块处理、协议与流水延时，而不只是单个乘加单元的正确性。需要同时提供功能证据与性能分析；本地模块测试通过不能自动证明集成系统正确，更不能代替基准程序测得的周期数。</p><p>课程还包含文献 / 项目报告。2026 秋笔记中的小组展示要求围绕近年的 AI system、AI chip 或 accelerator design 工作解释动机、方法与实验；不要用堆砌模型名称代替分析数据流和瓶颈。</p><h2 id="教材与资源" tabindex="-1">教材与资源 <a class="header-anchor" href="#教材与资源" aria-label="Permalink to &quot;教材与资源&quot;">​</a></h2><ul><li><a href="https://faculty.sist.shanghaitech.edu.cn/liust/EE219/EE219.html" target="_blank" rel="noreferrer">EE219 官方课程主页</a>：周历、Lab 与当学期通知。</li><li>《智能计算系统：从深度学习到大模型》第 2 版：当前公开主页列出的教材。</li><li>Patterson / Hennessy，<em>Computer Organization and Design</em>，RISC-V 版：当前公开主页所列参考。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/ai-hardware">AI 硬件自学</a>：补充量化、数据流与性能建模。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/research-guide/paper-reading">论文阅读指南</a>：用于硬件论文中基线与比较条件的核验。</li></ul><h2 id="往届经验与建议" tabindex="-1">往届经验与建议 <a class="header-anchor" href="#往届经验与建议" aria-label="Permalink to &quot;往届经验与建议&quot;">​</a></h2><p><strong>2026 秋版本。</strong> 当前官网列出 Lab 60%、Project 30%、Participation 10%，参与包括随堂测验与论坛活动等；不要把 10% 简化成只签到。当前列出的评分没有期末笔试项，仍应关注后续正式通知。</p><ul><li><strong>节奏</strong>：实验是持续性主要考核，不适合期末才补齐工程基础。</li><li><strong>难点</strong>：定点数的位宽 / 符号 / 溢出规则，脉动阵列的填充排空，以及分块边界和握手协议。</li><li><strong>准备</strong>：能用 Python 建立参考结果，能读波形和 RTL；进入 Lab4 时再按课程环境补充 Scala / Chisel，不擅自升级整套依赖。</li><li><strong>性能分析</strong>：先验算工作量和数据搬运，再测周期。分清理想峰值、有效利用率与端到端结果；计算强度只是诊断工具，不是实测性能。</li><li><strong>工具与诚信</strong>：遵守各实验自己的 AI 使用规定。Lab4 笔记记录需附 AI report 与使用过的 prompts，不应外推为其他作业也允许相同方式。</li></ul><h2 id="相关方向" tabindex="-1">相关方向 <a class="header-anchor" href="#相关方向" aria-label="Permalink to &quot;相关方向&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/research/ai-hardware">AI 硬件</a>：算子与加速器共同设计。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/research/architecture">计算机体系结构</a>：存储层次、数据流与系统瓶颈。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/research/digital-vlsi">数字 VLSI</a>：从架构到电路代价。</li></ul><div class="info custom-block"><p class="custom-block-title">征集</p><p>如果你修过这门课，欢迎通过<a href="/shanghaitech-ic-wiki-dev.github.io/about/contribute">参与共建</a>补充注明班级与学期的实验经验、环境差异和报告方法。不分享服务器凭据或整份作业实现。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://faculty.sist.shanghaitech.edu.cn/liust/EE219/EE219.html" target="_blank" rel="noreferrer">EE219 官方课程主页</a>：2026 秋公开周历、教材与评分；本页采集时主页标注更新于 2026/11/23。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">SIST 2026–2027 学年开课表</a>：先修与教师信息。</li><li>维护者笔记《智能计算系统》《EE219 Lab4 — Gemmini OS Tiling &amp; Mesh Integration》：实验与展示经验；不引用个人代码完成状态或未实测的性能。</li></ul>',22))])}const _=i(d,[["render",c]]);export{E as __pageData,_ as default};
